sections.code:
# ---- Trusting X-Forwarded-For correctly ----
#  Client(203.0.113.9) -> CDN(198.51.100.5) -> ALB(10.0.1.7) -> nginx -> app
#  X-Forwarded-For: 203.0.113.9, 198.51.100.5, 10.0.1.7
#                   ^ real client        ^ each hop appended what IT saw
#  A malicious client can PRESEND "X-Forwarded-For: 1.2.3.4" -- so never trust
#  the leftmost value blindly. Count trusted hops from the RIGHT.

# nginx: rewrite the client IP only for hops you actually operate
set_real_ip_from 10.0.0.0/8;          # your ALB / mesh subnets
set_real_ip_from 198.51.100.0/24;     # your CDN's published ranges
real_ip_header   X-Forwarded-For;
real_ip_recursive on;                 # walk right-to-left past trusted hops

# ---- Full reverse-proxy block with the headers that matter ----
location /api/ {
    proxy_pass http://api_upstream;
    proxy_http_version 1.1;
    proxy_set_header Host              $host;
    proxy_set_header X-Real-IP         $remote_addr;
    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;   # app builds correct https URLs
    proxy_set_header Connection        "";        # enable upstream keepalive

    proxy_connect_timeout 2s;
    proxy_send_timeout    30s;
    proxy_read_timeout    30s;

    proxy_buffering on;      # off => true streaming (SSE, chunked logs, LLM
                             # token streams); on => slow clients cannot tie up
                             # a backend worker. Choose deliberately.
}

# ---- Timeout ordering: get this wrong and you get unexplained 502/504 ----
#  REQUEST timeouts shrink inward:
#     client 30s  >  edge 25s  >  service 20s  >  database 5s
#  IDLE keepalive timeouts grow inward:
#     LB idle 60s  <  app keepalive 75s
#  If the app closes an idle pooled connection FIRST, the LB will hand a
#  request to a socket that is closing at that instant -> 502 Bad Gateway.
#     nginx:   keepalive_timeout 75s;
#     Node:    server.keepAliveTimeout = 75_000; server.headersTimeout = 76_000;
#     Go:      srv.IdleTimeout = 75 * time.Second

# ---- PROXY protocol: carrying the client IP when there is no HTTP header ----
# NLB / HAProxy sends a preamble BEFORE any application bytes:
#   PROXY TCP4 203.0.113.9 10.0.1.7 56324 443\r\n
# Both ends must agree, or the receiver sees garbage / a malformed request.
server {
    listen 8080 proxy_protocol;      # nginx: expect the preamble
    set_real_ip_from 10.0.0.0/8;
    real_ip_header proxy_protocol;
}

# ---- Safe retry policy (Envoy-style, and the reasoning is portable) ----
retry_policy:
  retry_on: "5xx,reset,connect-failure"
  num_retries: 2
  per_try_timeout: 2s
  retry_back_off: { base_interval: 0.025s, max_interval: 0.25s }  # + jitter
# and cap the blast radius so retries cannot amplify an overload:
#   retry budget: retries <= 10-20% of total requests
#   circuit breaker: eject a backend after N consecutive failures, cool down
#   NEVER blanket-retry POST without an idempotency key.
